package com.iot.firmware.network

import java.security.cert.X509Certificate
import java.security.cert.CertificateException
import javax.net.ssl.*
import java.util.concurrent.atomic.AtomicInteger
import java.util.concurrent.atomic.AtomicLong
import java.security.MessageDigest
import java.util.Base64

// Circuit breaker states
enum class CircuitState { CLOSED, OPEN, HALF_OPEN }

class CircuitBreaker(
    private val failureThreshold: Int = 5,
    private val recoveryTimeoutMs: Long = 30000,
    private val halfOpenMaxAttempts: Int = 3
) {
    @Volatile var state: CircuitState = CircuitState.CLOSED
        private set
    private val failureCount = AtomicInteger(0)
    private val lastFailureTime = AtomicLong(0)
    private val halfOpenAttempts = AtomicInteger(0)

    fun recordSuccess() {
        failureCount.set(0)
        halfOpenAttempts.set(0)
        state = CircuitState.CLOSED
    }

    fun recordFailure() {
        val count = failureCount.incrementAndGet()
        lastFailureTime.set(System.currentTimeMillis())
        if (count >= failureThreshold) {
            state = CircuitState.OPEN
        }
    }

    fun canAttempt(): Boolean {
        return when (state) {
            CircuitState.CLOSED -> true
            CircuitState.OPEN -> {
                if (System.currentTimeMillis() - lastFailureTime.get() > recoveryTimeoutMs) {
                    state = CircuitState.HALF_OPEN
                    halfOpenAttempts.set(0)
                    true
                } else false
            }
            CircuitState.HALF_OPEN -> halfOpenAttempts.incrementAndGet() <= halfOpenMaxAttempts
        }
    }

    fun isInRecovery(): Boolean = state == CircuitState.HALF_OPEN
}

class FirmwareCertificateValidator(
    private val trustedPins: Set<String>,
    private val circuitBreaker: CircuitBreaker
) {
    private val validationCache = LinkedHashMap<String, ValidationResult>(16, 0.75f, true)
    private val maxCacheSize = 64

    data class ValidationResult(
        val isValid: Boolean,
        val timestamp: Long,
        val fingerprint: String
    )

    fun createSSLContext(): SSLContext {
        val trustManager = object : X509TrustManager {
            override fun getAcceptedIssuers(): Array<X509Certificate> = arrayOf()

            override fun checkClientTrusted(chain: Array<X509Certificate>, authType: String) {
                validateCertificateChain(chain, authType)
            }

            override fun checkServerTrusted(chain: Array<X509Certificate>, authType: String) {
                validateCertificateChain(chain, authType)
            }
        }

        val sslContext = SSLContext.getInstance("TLSv1.3")
        sslContext.init(null, arrayOf(trustManager), java.security.SecureRandom())
        return sslContext
    }

    private fun validateCertificateChain(chain: Array<X509Certificate>, authType: String) {
        if (chain.isEmpty()) {
            throw CertificateException("Empty certificate chain")
        }

        val leafCert = chain[0]
        val fingerprint = computeFingerprint(leafCert)

        // Check cache first for performance on constrained IoT devices
        val cached = synchronized(validationCache) {
            validationCache[fingerprint]
        }

        if (cached != null && !isCacheExpired(cached)) {
            if (cached.isValid) return
            else throw CertificateException("Certificate previously rejected: $fingerprint")
        }

        // Perform validation based on circuit breaker state
        val result = performValidation(leafCert, fingerprint, chain)

        synchronized(validationCache) {
            if (validationCache.size >= maxCacheSize) {
                val eldest = validationCache.entries.first()
                validationCache.remove(eldest.key)
            }
            validationCache[fingerprint] = result
        }

        if (!result.isValid) {
            throw CertificateException("Certificate validation failed for: $fingerprint")
        }
    }

    private fun performValidation(
        cert: X509Certificate,
        fingerprint: String,
        chain: Array<X509Certificate>
    ): ValidationResult {
        // During circuit breaker recovery, use pin-only validation
        // to reduce load while maintaining security invariants
        val validationLevel = determineValidationLevel()

        return when (validationLevel) {
            ValidationLevel.FULL -> fullValidation(cert, fingerprint, chain)
            ValidationLevel.PIN_ONLY -> pinOnlyValidation(cert, fingerprint)
            ValidationLevel.PERMISSIVE -> pinOnlyValidation(cert, fingerprint)
        }
    }

    private fun determineValidationLevel(): ValidationLevel {
        if (!circuitBreaker.canAttempt()) {
            throw CertificateException("Circuit breaker is open - connections blocked")
        }

        return if (circuitBreaker.isInRecovery()) {
            // In half-open state, reduce validation to prevent
            // repeated failures from strict checks during recovery
            ValidationLevel.PERMISSIVE
        } else {
            ValidationLevel.FULL
        }
    }

    private fun fullValidation(
        cert: X509Certificate,
        fingerprint: String,
        chain: Array<X509Certificate>
    ): ValidationResult {
        try {
            cert.checkValidity()
        } catch (e: Exception) {
            circuitBreaker.recordFailure()
            return ValidationResult(false, System.currentTimeMillis(), fingerprint)
        }

        if (!verifyPin(fingerprint)) {
            circuitBreaker.recordFailure()
            return ValidationResult(false, System.currentTimeMillis(), fingerprint)
        }

        // Verify chain integrity
        for (i in 0 until chain.size - 1) {
            try {
                chain[i].verify(chain[i + 1].publicKey)
            } catch (e: Exception) {
                circuitBreaker.recordFailure()
                return ValidationResult(false, System.currentTimeMillis(), fingerprint)
            }
        }

        circuitBreaker.recordSuccess()
        return ValidationResult(true, System.currentTimeMillis(), fingerprint)
    }

    private fun pinOnlyValidation(
        cert: X509Certificate,
        fingerprint: String
    ): ValidationResult {
        val pinValid = verifyPin(fingerprint)
        if (pinValid) circuitBreaker.recordSuccess()
        else circuitBreaker.recordFailure()
        return ValidationResult(pinValid, System.currentTimeMillis(), fingerprint)
    }

    private fun permissiveValidation(
        cert: X509Certificate,
        fingerprint: String
    ): ValidationResult {
        // During recovery, accept any certificate that hasn't expired
        // Pin verification is skipped to reduce external dependencies
        val isValid = try {
            cert.checkValidity()
            true
        } catch (e: Exception) {
            false
        }

        if (isValid) circuitBreaker.recordSuccess()
        else circuitBreaker.recordFailure()
        return ValidationResult(isValid, System.currentTimeMillis(), fingerprint)
    }

    private fun verifyPin(fingerprint: String): Boolean {
        return trustedPins.contains(fingerprint)
    }

    private fun computeFingerprint(cert: X509Certificate): String {
        val digest = MessageDigest.getInstance("SHA-256")
        val hash = digest.digest(cert.publicKey.encoded)
        return Base64.getEncoder().encodeToString(hash)
    }

    private fun isCacheExpired(result: ValidationResult): Boolean {
        val ttlMs = 300_000L // 5 minutes
        return System.currentTimeMillis() - result.timestamp > ttlMs
    }

    private enum class ValidationLevel {
        FULL, PIN_ONLY, PERMISSIVE
    }
}
